export function AkarPorosLogo({
  showTagline = false,
  className = "",
  size = "md",
}: {
  showTagline?: boolean;
  className?: string;
  size?: "sm" | "md" | "lg";
}) {
  const sizeMap = {
    sm: { emblem: "w-7 h-7", title: "text-sm", sub: "text-[9px]" },
    md: { emblem: "w-9 h-9", title: "text-base", sub: "text-[10px]" },
    lg: { emblem: "w-14 h-14", title: "text-2xl", sub: "text-xs" },
  };

  const s = sizeMap[size];

  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <div className="relative shrink-0 flex items-center justify-center p-1.5 rounded-xl bg-[#0B3D2E] border border-[#4F6F5E]/30 shadow-md shadow-[#07261E]/50">
        <AkarPorosEmblem className={s.emblem} />
      </div>
      <div className="flex flex-col">
        <span
          className={`font-black tracking-wider text-[#F4F1E6] uppercase font-sans ${s.title}`}
        >
          Akar Poros
        </span>
        {showTagline && (
          <span className={`text-[#C7925B] font-medium tracking-wide ${s.sub}`}>
            Membangun sistem AI dari akarnya.
          </span>
        )}
      </div>
    </div>
  );
}
